1117	// normalizeRemoteURL converts any git remote URL to a plain HTTPS URL suitable for a browser.
1118	// Examples:
1119	//
1120	//	"git@gitlab.com:group/project.git"            → "https://gitlab.com/group/project"
1121	//	"https://token@gitlab.com/group/project.git"  → "https://gitlab.com/group/project"
1122	func normalizeRemoteURL(rawURL string) string {
1123		// SCP-like syntax: git@host:path
1124		if idx := strings.Index(rawURL, ":"); idx != -1 && !strings.Contains(rawURL[:idx], "/") {
1125			after := rawURL[idx+1:]
1126			if !strings.HasPrefix(after, "//") {
1127				host := rawURL[:idx]
1128				if at := strings.Index(host, "@"); at != -1 {
1129					host = host[at+1:]
1130				}
1131				return "https://" + host + "/" + strings.TrimSuffix(after, ".git")
1132			}
1133		}
1134		// URL syntax: strip credentials and .git suffix
1135		if idx := strings.Index(rawURL, "://"); idx != -1 {
1136			scheme := rawURL[:idx]
1137			rest := rawURL[idx+3:]
1138			if at := strings.Index(rest, "@"); at != -1 {
1139				if slash := strings.Index(rest, "/"); slash == -1 || at < slash {
1140					rest = rest[at+1:]
1141				}
1142			}
1143			return scheme + "://" + strings.TrimSuffix(rest, ".git")
1144		}
1145		return rawURL
1146	}
