1051	// applyTemplate downloads an OCI template and commits its files to the project.
1052	// This is a standalone function (not a method) because it runs inside a goroutine.
1053	func applyTemplate(client *gitlabclient.Client, projectID int, registryURL, username, password, repository, tag string) error {
1054		ociClient := oci.NewClient(registryURL, username, password)
1055	
1056		tmpl, err := ociClient.DownloadTemplate(repository, tag)
1057		if err != nil {
1058			return fmt.Errorf("download template: %w", err)
1059		}
1060	
1061		// Convert template files to commit actions
1062		actions := make([]gitlab.CommitAction, 0, len(tmpl.Files))
1063		for filePath, content := range tmpl.Files {
1064			actions = append(actions, gitlab.CommitAction{
1065				Action:   "create",
1066				FilePath: filePath,
1067				Content:  content,
1068			})
1069		}
1070	
1071		if len(actions) == 0 {
1072			return nil
1073		}
1074	
1075		return gitlab.InitializeProjectWithFiles(client, projectID, actions)
1076	}
